<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · CircularMenu</h1>
      <p class="demo-page__lead">
        定位方式从形态里拆出来了：组件 root 就是「按钮中心」这个锚点盒子，<code>position</code> /
        <code>anchor</code> / <code>offset</code> 决定它贴在哪里。默认 <code>position="relative"</code>，
        菜单就留在文档流里，跟着页面一起滚动；要 <code>sticky</code> / <code>fixed</code> /
        <code>absolute</code> 只是换一个属性值。下面两块示例分别演示随页面滚动和容器内吸顶，
        再往下是属性面板，可以把 <code>position</code> 切到 <code>fixed</code> / <code>absolute</code> 直接看效果。
      </p>
    </header>

    <section class="scroll-demo">
      <div class="scroll-demo__head">
        <h2 class="demo-page__section-title">随页面滚动</h2>
        <code class="scroll-demo__tag">position="relative"</code>
      </div>
      <p class="demo-card__text">滚动页面，菜单会跟着这一块一起移动。</p>
      <div class="scroll-demo__stage">
        <CircularMenu variant="wheel" :items="wheelItems" @select="onSelect" />
      </div>
    </section>

    <section class="scroll-demo">
      <div class="scroll-demo__head">
        <h2 class="demo-page__section-title">容器内吸顶</h2>
        <code class="scroll-demo__tag">position="sticky" anchor="top"</code>
      </div>
      <p class="demo-card__text">
        在下面这个滚动容器里往下滚，按钮会吸在容器顶部；<code>direction="auto"</code> 让贴顶的锚点自动向下展开，
        再点按钮或按 Esc 收起。
      </p>
      <div class="scroll-demo__box">
        <CircularMenu
          variant="wheel"
          position="sticky"
          anchor="top"
          :offset="12"
          :items="sheetItems"
          @select="onSelect"
        />
        <p v-for="n in 12" :key="n" class="scroll-demo__para">
          第 {{ n }} 段：这是一段用来撑开滚动条的内容。滚到这一段时，按钮会停在容器顶部，
          点开就是向下的扇形菜单。
        </p>
      </div>
    </section>

    <DemoPreview class="menu-preview">
      <LevaPlayground
        name="CircularMenu"
        :component="CircularMenu"
        :schema="CircularMenuSchema"
        :presets="{ items: menuItems }"
        :listeners="{ select: onSelect }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        最近点击：<strong>{{ picked }}</strong>。上面的面板来自组件包源码里的
        <code>propsSchema.json</code>：<code>position</code> / <code>anchor</code> / <code>offset</code> /
        <code>direction</code> 都生成了控件，改完马上能看到菜单换个贴法；<code>items</code> 这类复杂 props
        由 <code>presets</code> 固定传入。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { defineAsyncComponent, ref } from 'vue'
import CircularMenuSchema from '@melt-js/comps-vue3/src/components/CircularMenu.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { loadRemoteLib } from '../configs/remote'

/**
 * 与 RemoteView 相同的远程加载方式：入口处已 preFetchLib，这里只取组件。
 */
const CircularMenu = defineAsyncComponent({
  loader: async () => (await loadRemoteLib()).CircularMenu,
  timeout: 10000,
})

// 原 demo1 的 5 个图标位（图片/耳机/首页/视频/邮件），无图标字体，用单字代替
const wheelItems = [{ label: '图' }, { label: '乐' }, { label: '家' }, { label: '视' }, { label: '信' }]

// 原 demo2 的 7 个入口，由面板的 presets 固定传入（数组暂不生成控件）
const menuItems = [
  { label: '关于' },
  { label: '教程' },
  { label: '文章' },
  { label: '片段' },
  { label: '插件' },
  { label: '联系' },
  { label: '关注' },
]

// 吸顶那份换几个短标签，和上面两份区分开
const sheetItems = [{ label: '目录' }, { label: '收藏' }, { label: '分享' }, { label: '置顶' }]

/**
 * 属性面板的预览舞台：菜单默认是 relative，舞台用 flex 居中摆好；
 * 面板切到 absolute 时，stage 的 position: relative 就是它的定位祖先；
 * 切到 fixed 时按视口定位，不会再被 overflow 裁掉。
 * 背景用深色，白色按钮和红/绿扇环在上面看得清。
 */
const stageStyle = {
  position: 'relative',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '520px',
  background: '#2b3440',
}

const picked = ref('—')

function onSelect(item: { label: string }) {
  picked.value = item.label
}
</script>

